const rooms = new Map();
const COLORS = ["#78e8ff","#ff83c7","#b9a0ff","#ffe078","#75e5a5","#ff9b76"];
const IMPOSTER_TASKS = [
  { id: "reactor", name: "Reactor", x: 145, y: 125 },
  { id: "comms", name: "Communications", x: 450, y: 115 },
  { id: "engines", name: "Engines", x: 755, y: 365 }
];
const MAX_ROOM_PLAYERS = 16;
function getRoom(code) {
  if (!rooms.has(code)) rooms.set(code, { code, players: new Map(), connections: new Map(), imposter: null, wordGame: null, mindGame: null, objectGame: null, spellingGame: null });
  return rooms.get(code);
}
function sendTo(room, id, message) {
  const ws = room.connections.get(id);
  if (ws && ws.readyState === 1) ws.send(JSON.stringify(message));
}
function notifyRoom(code, text) {
  serverRef.publish(code, JSON.stringify({ type: "imposterNotice", text }));
}
function imposterState(room) {
  const game = room.imposter;
  if (!game) return null;
  const crewCount = Array.from(game.roles.values()).filter(role => role === "crew").length;
  let tasksDone = 0;
  for (const done of game.tasks.values()) tasksDone += done.size;
  const tasksTotal = crewCount * IMPOSTER_TASKS.length;
  const activePlayers = Array.from(room.players.values()).map(p => ({
    id: p.id, name: p.name, color: p.color, x: p.x, y: p.y,
    alive: p.alive !== false, spectator: game.roles.get(p.id) === "spectator",
    tasksDone: game.tasks.has(p.id) ? game.tasks.get(p.id).size : 0
  }));
  return {
    phase: game.phase, round: game.round, players: activePlayers,
    bodies: game.bodies.map(b => ({ x: b.x, y: b.y, name: b.name })),
    tasksDone, tasksTotal, votesCast: game.votes.size,
    winner: game.winner, lastEjected: game.lastEjected || "",
    deadline: game.deadline || null
  };
}
function publishImposter(code) {
  const room = rooms.get(code);
  if (!room || !room.imposter) return;
  serverRef.publish(code, JSON.stringify({ type: "imposterState", state: imposterState(room) }));
}
function sendImposterPrivate(room, id) {
  const game = room.imposter;
  if (!game) return;
  const role = game.roles.get(id) || "spectator";
  sendTo(room, id, {
    type: "imposterPrivate", role,
    completed: Array.from(game.tasks.get(id) || []),
    round: game.round
  });
}
function finishImposter(room, winner, text) {
  const game = room.imposter;
  if (!game) return;
  if (game.meetingTimer) clearTimeout(game.meetingTimer);
  game.meetingTimer = null;
  game.phase = "ended";
  game.winner = winner;
  game.deadline = null;
  game.lastEjected = text || "";
  publishImposter(room.code);
  notifyRoom(room.code, text || (winner === "crew" ? "Crew wins!" : "Imposters win!"));
}
function checkImposterWin(room) {
  const game = room.imposter;
  if (!game || game.phase === "ended" || game.phase === "lobby") return;
  const aliveCrew = Array.from(game.roles.entries()).filter(([id, role]) => role === "crew" && room.players.has(id) && room.players.get(id).alive !== false).length;
  const aliveImposters = Array.from(game.roles.entries()).filter(([id, role]) => role === "imposter" && room.players.has(id) && room.players.get(id).alive !== false).length;
  let tasksDone = 0;
  for (const done of game.tasks.values()) tasksDone += done.size;
  const crewCount = Array.from(game.roles.values()).filter(role => role === "crew").length;
  if (tasksDone >= crewCount * IMPOSTER_TASKS.length && crewCount > 0) finishImposter(room, "crew", "Crew completed every task!");
  else if (aliveImposters === 0) finishImposter(room, "crew", "All imposters were caught!");
  else if (aliveCrew <= aliveImposters) finishImposter(room, "imposters", "The imposters outnumber the remaining crew!");
}
function beginMeeting(room, text) {
  const game = room.imposter;
  if (!game || game.phase !== "active") return;
  game.phase = "discussion";
  game.votes = new Map();
  game.deadline = Date.now() + 25000;
  if (game.meetingTimer) clearTimeout(game.meetingTimer);
  const code = room.code;
  const round = game.round;
  game.meetingTimer = setTimeout(() => resolveMeeting(code, round), 25000);
  publishImposter(code);
  notifyRoom(code, text || "Emergency meeting! Discuss, then vote.");
}
function resolveMeeting(code, round) {
  const room = rooms.get(code);
  if (!room || !room.imposter || room.imposter.round !== round || room.imposter.phase !== "discussion") return;
  const game = room.imposter;
  if (game.meetingTimer) clearTimeout(game.meetingTimer);
  game.meetingTimer = null;
  const counts = new Map();
  for (const target of game.votes.values()) counts.set(target, (counts.get(target) || 0) + 1);
  const entries = Array.from(counts.entries()).sort((a,b) => b[1] - a[1]);
  let ejected = null;
  if (entries.length && entries[0][0] !== "skip" && (entries.length === 1 || entries[0][1] > entries[1][1])) {
    const target = entries[0][0];
    const player = room.players.get(target);
    if (player && player.alive !== false) {
      player.alive = false;
      const wasImposter = game.roles.get(target) === "imposter";
      ejected = player.name + (wasImposter ? " was an imposter." : " was not an imposter.");
      game.lastEjected = ejected;
    }
  } else {
    game.lastEjected = "No one was ejected.";
  }
  game.phase = "active";
  game.deadline = null;
  game.votes.clear();
  checkImposterWin(room);
  if (game.phase !== "ended") publishImposter(code);
  notifyRoom(code, game.lastEjected || "Back to the ship!");
}
function startImposter(room, code) {
  const list = Array.from(room.players.values());
  if (list.length < 4) {
    const ws = room.connections.get(code);
    if (ws) ws.send(JSON.stringify({ type: "imposterNotice", text: "You need at least 4 players to start. Invite the crew!" }));
    return;
  }
  const game = room.imposter || { round: 0 };
  if (game.meetingTimer) clearTimeout(game.meetingTimer);
  const round = (game.round || 0) + 1;
  const shuffled = list.slice().sort(() => Math.random() - 0.5);
  const impostersCount = list.length >= 12 ? 3 : list.length >= 8 ? 2 : 1;
  const roles = new Map();
  const tasks = new Map();
  const bodies = [];
  shuffled.forEach((p, index) => {
    const role = index < impostersCount ? "imposter" : "crew";
    roles.set(p.id, role);
    tasks.set(p.id, new Set());
    p.alive = true;
    p.x = 395 + (index % 4) * 36;
    p.y = 220 + Math.floor(index / 4) * 32;
    p.lastMoveAt = 0;
  });
  room.imposter = {
    phase: "active", round, roles, tasks, bodies, votes: new Map(),
    winner: null, lastEjected: "", emergencyUsed: false,
    killAt: new Map(), meetingTimer: null, deadline: null
  };
  for (const p of list) {
    const ws = room.connections.get(p.id);
    if (ws) ws.send(JSON.stringify({
      type: "imposterPrivate", role: roles.get(p.id),
      completed: [], round
    }));
  }
  publishImposter(code);
  notifyRoom(code, "Round " + round + " started! Roles are secret. Go!");
}

