let serverRef;
export default {
  port: Number(Bun.env.PORT || 8080),
  fetch(req, server) {
    serverRef = server;
    const url = new URL(req.url);
    if (url.pathname === "/health") return new Response("ok", { headers: { "content-type": "text/plain" } });
    if (url.pathname === "/ws") {
      const code = (url.searchParams.get("room") || "PUBLIC").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 10) || "PUBLIC";
      const room = getRoom(code);
      if (room.players.size >= MAX_ROOM_PLAYERS) return new Response("This room is full (16 players maximum).", { status: 403 });
      const name = (url.searchParams.get("name") || "Player").slice(0, 20);
      const data = { room: code, name, id: crypto.randomUUID(), color: COLORS[Math.floor(Math.random() * COLORS.length)] };
      if (server.upgrade(req, { data })) return;
      return new Response("WebSocket upgrade required", { status: 400 });
    }
    return new Response(html, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store",
        "x-content-type-options": "nosniff"
      }
    });
  },
  websocket: {
    open(ws) {
      const room = getRoom(ws.data.room);
      const p = { id: ws.data.id, name: ws.data.name, color: ws.data.color, x: 450, y: 250, alive: true };
      room.players.set(ws.data.id, p);
      room.connections.set(ws.data.id, ws);
      ws.subscribe(ws.data.room);
      ws.send(JSON.stringify({ type: "snapshot", selfId: ws.data.id, players: Array.from(room.players.values()) }));
      if (room.imposter && room.imposter.phase === "active" || room.imposter && room.imposter.phase === "discussion") {
        room.imposter.roles.set(ws.data.id, "spectator");
        p.alive = false;
        room.imposter.tasks.set(ws.data.id, new Set());
        sendImposterPrivate(room, ws.data.id);
        publishImposter(ws.data.room);
      } else if (room.imposter) {
        room.imposter.roles.set(ws.data.id, "spectator");
        sendImposterPrivate(room, ws.data.id);
        publishImposter(ws.data.room);
      }
      serverRef.publish(ws.data.room, JSON.stringify({ type: "players", players: Array.from(room.players.values()) }));
    },
    message(ws, raw) {
      let msg;
      try { msg = JSON.parse(String(raw)); } catch { return; }
      const room = getRoom(ws.data.room);
      const player = room.players.get(ws.data.id);
      if (!player) return;
      if (msg.type === "chat") {
        const text = String(msg.text || "").slice(0, 180).trim();
        if (!text) return;
        serverRef.publish(ws.data.room, JSON.stringify({ type: "chat", name: player.name, color: player.color, text }));
        return;
      }
      if (msg.type === "gameEvent") {
        const event = msg.event || {};
        const payload = JSON.stringify({ type: "gameEvent", gameId: String(msg.gameId || "").slice(0, 24), event, player });
        serverRef.publish(ws.data.room, payload);
        return;
      }

      if (msg.type === "wordAction") {
        const action=String(msg.action||"");
        if(action==="sync"){ws.send(JSON.stringify({type:"wordState",state:wordGamePublic(room)}));return}
        if(action==="start"){startWordGame(room);return}
        if(action==="guess"&&room.wordGame&&room.wordGame.phase==="active"){
          const guess=String(msg.guess||"").toLowerCase().replace(/[^a-z]/g,"").slice(0,32);if(!guess)return;
          const g=room.wordGame;g.guessCount++;const correct=guess===g.answer.toLowerCase();g.recentGuesses.push({name:player.name,text:guess,correct});
          if(correct){if(g.timer)clearTimeout(g.timer);g.phase="ended";g.winner=player.name;g.scores.set(player.id,(g.scores.get(player.id)||0)+3);publishWordGame(room);notifyRoom(ws.data.room,player.name+" guessed the word! +3 points 🎉")}
          else{g.recentGuesses=g.recentGuesses.slice(-20);publishWordGame(room)}
          return;
        }
        return;
      }
      if (msg.type === "mindAction") {
        const action=String(msg.action||"");
        if(action==="sync"){ws.send(JSON.stringify({type:"mindState",state:mindGamePublic(room)}));ws.send(JSON.stringify({type:"mindPrivate",submitted:!!(room.mindGame&&room.mindGame.responses.has(player.id))}));return}
        if(action==="start"){startMindGame(room);return}
        if(action==="submit"&&room.mindGame&&room.mindGame.phase==="answering"){
          const g=room.mindGame;if(g.responses.has(player.id))return;
          const answer=String(msg.answer||"").trim().replace(/\s+/g," ").slice(0,40);if(!answer)return;
          g.responses.set(player.id,{name:player.name,answer,normalized:answer.toLowerCase().replace(/[^a-z0-9]/g,""),points:0});
          sendTo(room,player.id,{type:"mindPrivate",submitted:true});
          const activeIds=Array.from(room.players.keys()).filter(id=>room.connections.has(id));
          if(activeIds.every(id=>g.responses.has(id)))resolveMindGame(room,g.round);else publishMindGame(room);
          return;
        }
        return;
      }


      if (msg.type === "objectAction") {
        const action=String(msg.action||"");
        if(action==="sync"){if(!room.objectGame)room.objectGame={phase:"lobby",round:0,roles:new Map(),clues:new Map(),timer:null,guessesRemaining:2};const g=room.objectGame;if(g.phase!=="lobby"&&g.phase!=="ended"&&!g.roles.has(player.id))g.roles.set(player.id,"spectator");sendObjectPrivate(room,player.id);ws.send(JSON.stringify({type:"objectState",state:objectGamePublic(room)}));return}
        if(action==="start"){startObjectGame(room);return}
        const g=room.objectGame;if(!g)return;const role=g.roles.get(player.id);
        if(action==="clue"&&g.phase==="clues"&&role==="crew"&&!g.clues.has(player.id)){
          const clue=String(msg.clue||"").trim().replace(/\s+/g," ").slice(0,90);if(clue.length<3){ws.send(JSON.stringify({type:"imposterNotice",text:"Give a slightly longer clue."}));return}
          const norm=s=>String(s||"").toLowerCase().replace(/[^a-z0-9]/g,"");if(norm(clue).includes(norm(g.answer))){ws.send(JSON.stringify({type:"imposterNotice",text:"Your clue says the secret object. Describe it without naming it!"}));return}
          g.clues.set(player.id,clue);publishObjectGame(room);maybeAdvanceObject(room);return;
        }
        if(action==="guess"&&g.phase==="guessing"&&role==="imposter"){const guess=String(msg.guess||"").trim().slice(0,50);if(!guess)return;const norm=s=>String(s||"").toLowerCase().replace(/[^a-z0-9]/g,"");if(norm(guess)===norm(g.answer))finishObjectGame(room,"imposter",player.name+" guessed the secret object! Imposter wins!");else{g.guessesRemaining--;if(g.guessesRemaining<=0)finishObjectGame(room,"crew","The imposter used both guesses. Crewmates win!");else{publishObjectGame(room);notifyRoom(room.code,"Not quite! The imposter has one guess left.")}}return}
        return;
      }
      if (msg.type === "spellingAction") {
        const action=String(msg.action||"");
        if(action==="sync"){if(!room.spellingGame)room.spellingGame={phase:"lobby",round:0,scores:new Map(),roster:new Set(),responses:new Map(),names:new Map(),timer:null};const g=room.spellingGame;if(g.phase==="active"&&!g.roster.has(player.id)){g.roster.add(player.id);g.names.set(player.id,player.name)}ws.send(JSON.stringify({type:"spellingState",state:spellingGamePublic(room)}));sendSpellingPrivate(room,player.id);return}
        if(action==="start"){startSpellingGame(room);return}
        const g=room.spellingGame;if(action==="submit"&&g&&g.phase==="active"&&g.roster.has(player.id)&&!g.responses.has(player.id)){const spelling=String(msg.spelling||"").trim().slice(0,48);if(!spelling)return;g.responses.set(player.id,{spelling,correct:false});const active=Array.from(g.roster).filter(id=>room.connections.has(id));if(active.every(id=>g.responses.has(id)))resolveSpellingGame(room,g.round);else publishSpellingGame(room);return}
        return;
      }

      if (msg.type !== "imposterAction") return;
      const game = room.imposter;
      const action = String(msg.action || "");
      if (action === "sync") {
        if (!room.imposter) {
          room.imposter = {
            phase: "lobby", round: 0, roles: new Map(), tasks: new Map(),
            bodies: [], votes: new Map(), winner: null, lastEjected: "",
            emergencyUsed: false, killAt: new Map(), meetingTimer: null, deadline: null
          };
        }
        const lobby = room.imposter;
        if (!lobby.roles.has(ws.data.id)) lobby.roles.set(ws.data.id, "spectator");
        if (!lobby.tasks.has(ws.data.id)) lobby.tasks.set(ws.data.id, new Set());
        sendImposterPrivate(room, ws.data.id);
        ws.send(JSON.stringify({ type: "imposterState", state: imposterState(room) }));
        return;
      }
      if (action === "start") {
        startImposter(room, ws.data.room);
        return;
      }
      if (!game) return;
      const role = game.roles.get(ws.data.id);
      if (action === "move" && game.phase === "active" && role && role !== "spectator" && player.alive !== false) {
        const now = Date.now();
        if (now - (player.lastMoveAt || 0) < 65) return;
        player.lastMoveAt = now;
        player.x = Math.max(35, Math.min(865, Number(msg.x) || player.x));
        player.y = Math.max(40, Math.min(460, Number(msg.y) || player.y));
        publishImposter(ws.data.room);
        return;
      }
      if (action === "task" && game.phase === "active" && role === "crew" && player.alive !== false) {
        const station = IMPOSTER_TASKS.find(s => s.id === msg.station);
        if (!station || Math.hypot(player.x - station.x, player.y - station.y) > 72) {
          ws.send(JSON.stringify({ type: "imposterNotice", text: "Move closer to a glowing station first." }));
          return;
        }
        const done = game.tasks.get(ws.data.id) || new Set();
        if (done.has(station.id)) {
          ws.send(JSON.stringify({ type: "imposterNotice", text: "You already completed that station." }));
          return;
        }
        done.add(station.id);
        game.tasks.set(ws.data.id, done);
        ws.send(JSON.stringify({ type: "imposterPrivate", role, completed: Array.from(done), round: game.round }));
        notifyRoom(ws.data.room, player.name + " completed a ship task.");
        checkImposterWin(room);
        publishImposter(ws.data.room);
        return;
      }
      if (action === "kill" && game.phase === "active" && role === "imposter" && player.alive !== false) {
        const now = Date.now();
        if (now - (game.killAt.get(ws.data.id) || 0) < 10000) {
          ws.send(JSON.stringify({ type: "imposterNotice", text: "Sabotage is cooling down." }));
          return;
        }
        const targets = Array.from(game.roles.entries())
          .filter(([id, targetRole]) => targetRole === "crew" && room.players.has(id) && room.players.get(id).alive !== false)
          .map(([id]) => room.players.get(id))
          .sort((a,b) => Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y));
        const target = targets[0];
        if (!target || Math.hypot(target.x-player.x,target.y-player.y) > 62) {
          ws.send(JSON.stringify({ type: "imposterNotice", text: "Get closer to a crewmate to sabotage." }));
          return;
        }
        target.alive = false;
        game.killAt.set(ws.data.id, now);
        game.bodies.push({ x: target.x, y: target.y, name: target.name });
        notifyRoom(ws.data.room, "A crewmate has disappeared… find the body!");
        checkImposterWin(room);
        publishImposter(ws.data.room);
        return;
      }
      if (action === "report" && game.phase === "active" && role && role !== "spectator" && player.alive !== false) {
        const unreported = game.bodies.length > 0;
        if (!unreported && game.emergencyUsed) {
          ws.send(JSON.stringify({ type: "imposterNotice", text: "The emergency meeting has already been used." }));
          return;
        }
        if (!unreported) game.emergencyUsed = true;
        beginMeeting(room, unreported ? player.name + " reported a body!" : player.name + " called an emergency meeting!");
        if (unreported) { game.bodies.length = 0; publishImposter(ws.data.room); }
        return;
      }
      if (action === "vote" && game.phase === "discussion" && role && role !== "spectator" && player.alive !== false) {
        const target = String(msg.target || "skip");
        if (target !== "skip") {
          if (!room.players.has(target) || room.players.get(target).alive === false || game.roles.get(target) === "spectator") return;
        }
        game.votes.set(ws.data.id, target);
        const alive = Array.from(game.roles.keys()).filter(id => room.players.has(id) && room.players.get(id).alive !== false && game.roles.get(id) !== "spectator");
        if (alive.every(id => game.votes.has(id))) resolveMeeting(ws.data.room, game.round);
        else publishImposter(ws.data.room);
        return;
      }
    },
    close(ws) {
      const room = rooms.get(ws.data.room);
      if (!room) return;
      room.players.delete(ws.data.id);
      room.connections.delete(ws.data.id);
      if(room.objectGame){const role=room.objectGame.roles.get(ws.data.id);room.objectGame.roles.delete(ws.data.id);room.objectGame.clues.delete(ws.data.id);if(role==="imposter"&&room.objectGame.phase!=="ended")finishObjectGame(room,"crew","The imposter left. Crewmates win!");else maybeAdvanceObject(room)}
      if(room.spellingGame&&room.spellingGame.phase==="active"){room.spellingGame.roster.delete(ws.data.id);const active=Array.from(room.spellingGame.roster).filter(id=>room.connections.has(id));if(active.length&&active.every(id=>room.spellingGame.responses.has(id)))resolveSpellingGame(room,room.spellingGame.round);else publishSpellingGame(room)}
      if (room.imposter) {
        room.imposter.roles.delete(ws.data.id);
        room.imposter.tasks.delete(ws.data.id);
        room.imposter.votes.delete(ws.data.id);
        checkImposterWin(room);
        if (room.imposter.phase !== "ended") publishImposter(ws.data.room);
      }
      serverRef.publish(ws.data.room, JSON.stringify({ type: "players", players: Array.from(room.players.values()) }));
      if (!room.players.size) {
        if (room.imposter && room.imposter.meetingTimer) clearTimeout(room.imposter.meetingTimer);
        if(room.objectGame&&room.objectGame.timer)clearTimeout(room.objectGame.timer);
        if(room.spellingGame&&room.spellingGame.timer)clearTimeout(room.spellingGame.timer);
        rooms.delete(ws.data.room);
      }
    }
  }
};
